import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

/** Default colour for labels an import has to create. */
const IMPORTED_LABEL_COLOR = "#94a3b8";

export interface IssueImportRecord {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

export interface ImportedIssueRow {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  /** Label names, already de-duplicated. */
  readonly labelNames: readonly string[];
}

export interface InsertImportInput {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportedIssueRow[];
}

export type InsertImportOutcome =
  | { readonly kind: "created"; readonly issues: readonly Issue[] }
  | { readonly kind: "replayed"; readonly record: IssueImportRecord };

type Tx = Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0];

function readImport(
  db: Tx | ReturnType<typeof getDb>,
  orgId: OrgId,
  importKey: string,
): IssueImportRecord | null {
  const row = db
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;
  return {
    projectId: row.projectId as ProjectId,
    issueIds: JSON.parse(row.issueIds) as IssueId[],
  };
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  return readImport(getDb(), orgId, importKey);
}

/**
 * Writes the batch. Re-checks the key inside the transaction so two uploads
 * racing on the same key cannot both create issues.
 */
export async function insertImport(
  input: InsertImportInput,
): Promise<InsertImportOutcome> {
  return getDb().transaction((tx): InsertImportOutcome => {
    const existing = readImport(tx, input.orgId, input.importKey);
    if (existing) return { kind: "replayed", record: existing };

    const stamp = toIsoTimestamp(new Date());
    const labelIdByName = resolveLabels(tx, input, stamp);

    const max = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let nextNumber = (max?.value ?? 0) + 1;

    const created: Issue[] = [];
    for (const row of input.rows) {
      const inserted = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          number: nextNumber++,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = row.labelNames.map(
        (name) => labelIdByName.get(name) as LabelId,
      );
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }

      created.push(toIssue(inserted, labelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        importKey: input.importKey,
        importedBy: input.authorId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { kind: "created", issues: created };
  });
}

/** Finds the org's labels by exact name, creating the missing ones once. */
function resolveLabels(
  tx: Tx,
  input: InsertImportInput,
  stamp: IsoTimestamp,
): ReadonlyMap<string, LabelId> {
  const names = [...new Set(input.rows.flatMap((row) => row.labelNames))];
  const byName = new Map<string, LabelId>();
  if (names.length === 0) return byName;

  const existing = tx
    .select({ id: labels.id, name: labels.name })
    .from(labels)
    .where(
      and(orgPredicate(labels.orgId, input.orgId), inArray(labels.name, names)),
    )
    .all();
  for (const label of existing) {
    // SQLite's default collation is binary, so this match is case-sensitive.
    byName.set(label.name, label.id as LabelId);
  }

  for (const name of names) {
    if (byName.has(name)) continue;
    const row = tx
      .insert(labels)
      .values({
        id: newId(),
        orgId: input.orgId,
        name,
        color: IMPORTED_LABEL_COLOR,
        description: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning({ id: labels.id })
      .get();
    byName.set(name, row.id as LabelId);
  }

  return byName;
}
